'use client';
import { createContext, useContext, useState } from 'react';

const YearFilterContext = createContext();

export function YearFilterProvider({ children }) {
  const currentYear = new Date().getFullYear().toString();
  const [yearFilter, setYearFilter] = useState(currentYear);
  
  return (
    <YearFilterContext.Provider value={{ yearFilter, setYearFilter }}>
      {children}
    </YearFilterContext.Provider>
  );
}

export const useYearFilter = () => useContext(YearFilterContext);